def get_flow_size_slowdown_pairs_list(
    byteload_size_B, inter_byteload_interval_nanosec, rtt_s,
    flowsize_fct_s_pairs_list
):
    flowsize_slowdown_pairs_list = []
    for flow_size_B, fct_s in flowsize_fct_s_pairs_list:
        ideal_fct_s = dale_fe_analyse_fct_slowdown.get_theoretical_fct_single_flow_s(
            flow_size_B=flow_size_B,
            byteload_size_B=byteload_size_B,
            inter_byteload_interval_nanosec=inter_byteload_interval_nanosec,
            rtt_s=rtt_s
        )
        slowdown = fct_s/ideal_fct_s
        flowsize_slowdown_pairs_list.append((flow_size_B, slowdown))
    return flowsize_slowdown_pairs_list

def get_flows_in_size_range(min_flow_size_B, max_flow_size_B, flowsize_slowdown_pairs_list):
    target_flowsize_slowdown_pairs_list = []
    for flowsize, slowdown in flowsize_slowdown_pairs_list:
        if (min_flow_size_B <= flowsize and flowsize <= max_flow_size_B):
            target_flowsize_slowdown_pairs_list.append((flowsize, slowdown))
    return target_flowsize_slowdown_pairs_list

def get_flow_size_range_groups_slowdown(mss_B, bdp_B, flowsize_slowdown_pairs_list):
        # sort flow sizes into groups:
        # size ranges: 0 ≤ A < MSS ≤ B < 1 × BDP ≤ C < 8 × BDP ≤ D
        range_A_flowsize_slowdown_pairs_list = get_flows_in_size_range(
            min_flow_size_B=0,
            max_flow_size_B=mss_B-1,
            flowsize_slowdown_pairs_list=flowsize_slowdown_pairs_list
        )
        range_B_flowsize_slowdown_pairs_list = get_flows_in_size_range(
            min_flow_size_B=mss_B,
            max_flow_size_B=bdp_B-1,
            flowsize_slowdown_pairs_list=flowsize_slowdown_pairs_list
        )
        range_C_flowsize_slowdown_pairs_list = get_flows_in_size_range(
            min_flow_size_B=bdp_B,
            max_flow_size_B=8*bdp_B-1,
            flowsize_slowdown_pairs_list=flowsize_slowdown_pairs_list
        )
        range_D_flowsize_slowdown_pairs_list = get_flows_in_size_range(
            min_flow_size_B=8*bdp_B,
            max_flow_size_B=math.inf,
            flowsize_slowdown_pairs_list=flowsize_slowdown_pairs_list
        )
        range_A_slowdown_list = [slowdown for flowsize, slowdown in range_A_flowsize_slowdown_pairs_list]
        range_B_slowdown_list = [slowdown for flowsize, slowdown in range_B_flowsize_slowdown_pairs_list]
        range_C_slowdown_list = [slowdown for flowsize, slowdown in range_C_flowsize_slowdown_pairs_list]
        range_D_slowdown_list = [slowdown for flowsize, slowdown in range_D_flowsize_slowdown_pairs_list]
        print(f"srpt: range A: {len(range_A_slowdown_list)} flows")
        print(f"srpt: range B: {len(range_B_slowdown_list)} flows")
        print(f"srpt: range C: {len(range_C_slowdown_list)} flows")
        print(f"srpt: range D: {len(range_D_slowdown_list)} flows")
        return range_A_slowdown_list, range_B_slowdown_list, range_C_slowdown_list, range_D_slowdown_list

