def plot_slowdown_vs_flowsize_ranges_ssird_policy(
    graph_title,
    experiment_family, title_addendum, experiment_date,
    byteload_size_B, inter_byteload_interval_nanosec, rtt_s,
    num_flows_list,
    incast_degree,  # is `n` in `n-to-1` incast; i.e. how many senders are sending to a single receiver
    target_num_flows,   # is the num flows that we want to analyse (corresponds to a chosen app load)
    ssird_srpt_flowsize_fct_s_pairs_list_list,
    ssird_fairshare_flowsize_fct_s_pairs_list_list,
    percentile,
    y_lim=None
):

    print([len(list) for list in ssird_srpt_flowsize_fct_s_pairs_list_list])
    print([len(list) for list in ssird_fairshare_flowsize_fct_s_pairs_list_list])

    assert(len(set([
        len(ssird_srpt_flowsize_fct_s_pairs_list_list),
        len(ssird_fairshare_flowsize_fct_s_pairs_list_list),
        len(num_flows_list)
    ]))==1)

    num_experiments = len(num_flows_list)
    for i in range(num_experiments):
        assert(num_flows_list[i]*incast_degree == len(ssird_srpt_flowsize_fct_s_pairs_list_list[i]))

    for i in range(num_experiments):
        num_flows = num_flows_list[i]
        if (num_flows != target_num_flows):
            continue

        ssird_srpt_flowsize_slowdown_pairs_list = get_flow_size_slowdown_pairs_list(
            byteload_size_B=byteload_size_B,
            inter_byteload_interval_nanosec=inter_byteload_interval_nanosec,
            rtt_s=rtt_s,
            flowsize_fct_s_pairs_list=ssird_srpt_flowsize_fct_s_pairs_list_list[i]
        )
        ssird_srpt_slowdown_list_all = [slowdown for size, slowdown in ssird_srpt_flowsize_slowdown_pairs_list]

        ssird_fairshare_flowsize_slowdown_pairs_list = get_flow_size_slowdown_pairs_list(
            byteload_size_B=byteload_size_B,
            inter_byteload_interval_nanosec=inter_byteload_interval_nanosec,
            rtt_s=rtt_s,
            flowsize_fct_s_pairs_list=ssird_fairshare_flowsize_fct_s_pairs_list_list[i]
        )
        ssird_fairshare_slowdown_list_all = [slowdown for size, slowdown in ssird_fairshare_flowsize_slowdown_pairs_list]

        # sort flow sizes into groups:
        # size ranges: 0 ≤ A < MSS ≤ B < 1 × BDP ≤ C < 8 × BDP ≤ D
        MSS = 1458
        BDP = math.ceil(LINK_SPEED_BITS_PER_SEC*RTT_5US_S/8)
        # print(BDP)
        # SRPT
        ssird_srpt_slowdown_tuple = get_flow_size_range_groups_slowdown(MSS, BDP, ssird_srpt_flowsize_slowdown_pairs_list)
        range_A_slowdown_list_ssird_srpt, range_B_slowdown_list_ssird_srpt, range_C_slowdown_list_ssird_srpt, range_D_slowdown_list_ssird_srpt = ssird_srpt_slowdown_tuple

        # Fairshare
        ssird_fairshare_slowdown_tuple = get_flow_size_range_groups_slowdown(MSS, BDP, ssird_fairshare_flowsize_slowdown_pairs_list)
        range_A_slowdown_list_ssird_fairshare, range_B_slowdown_list_ssird_fairshare, range_C_slowdown_list_ssird_fairshare, range_D_slowdown_list_ssird_fairshare = ssird_fairshare_slowdown_tuple

        # make pandas stats df for ssird srpt
        ssird_srpt_series_list = [
            pd.Series(range_A_slowdown_list_ssird_srpt, name="A"),
            pd.Series(range_B_slowdown_list_ssird_srpt, name="B"),
            pd.Series(range_C_slowdown_list_ssird_srpt, name="C"),
            pd.Series(range_D_slowdown_list_ssird_srpt, name="D"),
            pd.Series(ssird_srpt_slowdown_list_all, name="All")
        ]        
        # Calculate statistics for each series
        ssird_srpt_stats_data = []
        for series in ssird_srpt_series_list:
            ssird_srpt_stats_data.append({
                'set_name': "ssird_srpt", 
                'category': series.name,
                'median': series.median(),
                'p90': series.quantile(round(percentile/100, 1)),
                'count': series.count()
            })
        ssird_srpt_stats_df = pd.DataFrame(ssird_srpt_stats_data)

        # make pandas stats df for ssird srpt
        ssird_fairshare_series_list = [
            pd.Series(range_A_slowdown_list_ssird_fairshare, name="A"),
            pd.Series(range_B_slowdown_list_ssird_fairshare, name="B"),
            pd.Series(range_C_slowdown_list_ssird_fairshare, name="C"),
            pd.Series(range_D_slowdown_list_ssird_fairshare, name="D"),
            pd.Series(ssird_fairshare_slowdown_list_all, name="All")
        ]        
        # Calculate statistics for each series
        ssird_fairshare_stats_data = []
        for series in ssird_fairshare_series_list:
            ssird_fairshare_stats_data.append({
                'set_name': "ssird_fairshare", 
                'category': series.name,
                'median': series.median(),
                'p90': series.quantile(round(percentile/100, 1)),
                'count': series.count()
            })
        ssird_fairshare_stats_df = pd.DataFrame(ssird_fairshare_stats_data)


        # create df for both sets (ssird srpt, fairshare)
        combined_df = pd.concat([ssird_srpt_stats_df, ssird_fairshare_stats_df], ignore_index=True)
        # Pivot for easier plotting
        pivot_df = combined_df.set_index(['category', 'set_name']).unstack('set_name')
        print(pivot_df)

        # fig, ax = plt.subplots(figsize=(12,7))
        fig, ax = plt.subplots(figsize=(12,6))
        # fig.tight_layout()

        categories = list(["A", "B", "C", "D", "All"])
        x_pos = np.arange(len(categories))
        width = 0.35  # Width of each bar
        # Colors for each set
        colors = {'ssird_srpt': '#ff7f0e', 'ssird_fairshare': '#1f77b4'}

        # Plot bars for both sets
        custom_labels = {
            'ssird_srpt': 'SSIRD (SRPT)',
            'ssird_fairshare': 'SSIRD (Fairshare)', 
        }
        custom_cateogry_names = {
            'A': '0 ≤ Size < MSS',
            'B': 'MSS ≤ Size < 1xBDP', 
            'C': '1xBDP ≤ Size < 8xBDP',
            'D': '8xBDP < Size',
            'All': 'All Sizes'
        }
        categories_for_display = [custom_cateogry_names[cat] for cat in categories]
        for i, set_name in enumerate(['ssird_srpt', 'ssird_fairshare']):
            offset = -width/2 if set_name == 'ssird_srpt' else width/2
            median_values = [pivot_df[('median', set_name)][cat] for cat in categories]
            bars = ax.bar(x_pos + offset, median_values, width,
                        color=colors[set_name], alpha=0.8, edgecolor='black', linewidth=1,
                        label=custom_labels[set_name], capsize=5)
        # Add whiskers for both sets
        for i, category in enumerate(categories):
            for j, set_name in enumerate(['ssird_srpt', 'ssird_fairshare']):
                offset = -width/2 if set_name == 'ssird_srpt' else width/2
                median_val = pivot_df[('median', set_name)][category]
                p90_val = pivot_df[('p90', set_name)][category]
                whisker_color = colors[set_name]  # Use the same color as bars
                # Draw whisker line
                ax.plot([i + offset, i + offset], [median_val, p90_val],
                        color=whisker_color, linewidth=2, alpha=0.8)
                # Draw whisker cap
                ax.plot([i + offset - 0.05, i + offset + 0.05], [p90_val, p90_val],
                        color=whisker_color, linewidth=2, alpha=0.8)

        # Calculate and Set x-axis labels and ticks:
        set_percentages = {'ssird_srpt': {}, 'ssird_fairshare': {}}
        # Total elements for each set
        total_srpt = ssird_srpt_stats_df[ssird_srpt_stats_df['category'] != 'All']['count'].sum()
        total_fairshare = ssird_fairshare_stats_df[ssird_fairshare_stats_df['category'] != 'All']['count'].sum()
        for category in categories:
            # Get counts for this category from both sets
            count_srpt = ssird_srpt_stats_df[ssird_srpt_stats_df['category'] == category]['count'].values[0]
            count_fairshare = ssird_fairshare_stats_df[ssird_fairshare_stats_df['category'] == category]['count'].values[0]
            # Calculate percentages within each set
            srpt_pct = (count_srpt / total_srpt) * 100
            fairshare_pct = (count_fairshare / total_fairshare) * 100
            set_percentages['ssird_srpt'][category] = srpt_pct
            set_percentages['ssird_fairshare'][category] = fairshare_pct
        # Create x-axis labels with within-set percentages
        x_labels = []
        for category, category_display in zip(categories, categories_for_display):
            srpt_pct = set_percentages['ssird_srpt'][category]
            fairshare_pct = set_percentages['ssird_fairshare'][category]
            # x_labels.append(f"{category}\n(SRPT: {srpt_pct:.0f}%)\n(FS: {fairshare_pct:.0f}%)")
            x_labels.append(f"{category_display}\n({srpt_pct:.0f}%)") # all sets (srpt, fairshare) have the same percentage cuz they use the same flows
        # Add a vertical line to separate "All" from the other categories
        ax.axvline(x=len(categories)-2+0.5, color='gray', linestyle='--', alpha=0.7, linewidth=1)

        ax.set_xticks(x_pos)
        ax.set_xticklabels(x_labels, fontsize=10)

        # Add plot labels and title
        ax.set_xlabel('Flow Size Range Categories')
        ax.set_ylabel('Slowdown')
        ax.set_title(f'SSIRD Policy Slowdown Comparison (Median Bars, {percentile}th Percentile Whiskers)\n{graph_title}')
        # ax.set_title(f'Slowdown Comparison (Median with {percentile}th Percentile Whiskers) \
        #              \n{graph_title}   \
        #              \n{experiment_family}{title_addendum}{experiment_date}' \
        #              )
        ax.legend()
        ax.grid(axis='y', alpha=0.3)        
        if (y_lim): ax.set_ylim(y_lim)

        plt.legend()

        num_flows_total = num_flows*incast_degree
        Path(PATH_TO_FLOW_SLOWDOWN_VS_FLOWSIZE_RANGE).mkdir(parents=True, exist_ok=True)
        filename = f"ssird_policy_slowdown_vs_flowsize_{num_flows_total}flo_{experiment_family}{title_addendum}_{experiment_date}.png"
        plt.savefig(f"{PATH_TO_FLOW_SLOWDOWN_VS_FLOWSIZE_RANGE}{filename}")
        plt.close()
        # return

